--
-- Name: get_wallet_balance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_wallet_balance(p_account_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_balance BIGINT;
BEGIN
    SELECT
        COALESCE(SUM(
            CASE le.direction
                WHEN 'CREDIT' THEN  le.amount_paise
                WHEN 'DEBIT'  THEN -le.amount_paise
            END
        ), 0)
    INTO v_balance
    FROM ledger_entries le
    JOIN payment_transactions pt ON pt.id = le.transaction_id
    WHERE le.account_id = p_account_id
      AND pt.status = 'SUCCESS';

    RETURN v_balance;
END;
$$;


