--
-- Name: handle_before_user_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_before_user_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
        id, 
        phone, 
        email, 
        raw_user_meta_data, 
        created_at, 
        updated_at, 
        instance_id, 
        aud, 
        role
    )
    VALUES (
        NEW.id,
        NEW.phone,
        NEW.email,
        jsonb_build_object('role', NEW.role, 'login_id', NEW.login_id),
        NOW(),
        NOW(),
        '00000000-0000-0000-0000-000000000000',
        'authenticated',
        'authenticated'
    )
    ON CONFLICT (id) DO UPDATE
    SET phone = EXCLUDED.phone,
        email = EXCLUDED.email;
    RETURN NEW;
END;
$$;


