    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN EXISTS (
        SELECT 1
        FROM work_contracts wc
        JOIN workers w ON w.id = wc.worker_id
        WHERE w.user_id = p_worker_user_id
          AND wc.project_id = p_project_id
    );
END;
$$;


