-- Name: prevent_role_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_role_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    IF (TG_OP = 'UPDATE' AND NEW.role IS DISTINCT FROM OLD.role) THEN
        IF (auth.role() = 'authenticated' OR current_user = 'authenticated') THEN
            RAISE EXCEPTION 'PRIVILEGE_ESCALATION_FORBIDDEN: Client is prohibited from modifying user role from % to %.', OLD.role, NEW.role
                USING ERRCODE = '42501';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: prevent_update_or_delete_append_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_update_or_delete_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'TAMPER_PREVENTION_ERROR: Table % is append-only. UPDATE and DELETE operations are strictly prohibited.', TG_TABLE_NAME
    USING ERRCODE = '27000';
END;
$$;


--
-- Name: reverse_payment_with_ledger(uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_payment_with_ledger(p_original_transaction_id uuid, p_reversal_ref text, p_reversal_idempotency_key text, p_initiated_by uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_original      payment_transactions;
    v_reversal      payment_transactions;
    v_sender_bal    BIGINT;
    v_receiver_bal  BIGINT;
BEGIN
    -- Fetch original transaction (lock it for update)
    SELECT * INTO v_original
    FROM payment_transactions
    WHERE id = p_original_transaction_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'TRANSACTION_NOT_FOUND: Original transaction % does not exist', p_original_transaction_id;
    END IF;

    IF v_original.status <> 'SUCCESS' THEN
        RAISE EXCEPTION 'INVALID_REVERSAL: Only SUCCESS transactions can be reversed. Status: %', v_original.status;
    END IF;

    -- Insert reversal transaction (sender/receiver swapped)
        transaction_ref,
        idempotency_key,
        sender_account_id,
        receiver_account_id,
        worker_id,
        contractor_id,
        contract_id,
        project_id,
        amount_paise,
        payment_source,
        status,
        notes,
        initiated_by
    ) VALUES (
        p_reversal_ref,
        p_reversal_idempotency_key,
        v_original.receiver_account_id,  -- reversed: worker sends back
        v_original.sender_account_id,    -- reversed: contractor receives back
        v_original.worker_id,
        v_original.contractor_id,
        v_original.contract_id,
        v_original.project_id,
        v_original.amount_paise,
        v_original.payment_source,
        'PROCESSING',
        'REVERSAL of ' || v_original.transaction_ref || '. Reason: ' || COALESCE(p_reason, 'Not specified'),
        p_initiated_by
    )
    RETURNING * INTO v_reversal;

    -- Running balances
    v_sender_bal   := get_wallet_balance(v_original.receiver_account_id);
    v_receiver_bal := get_wallet_balance(v_original.sender_account_id);

    -- DEBIT the receiver (worker) — taking back the amount
    VALUES (v_reversal.id, v_original.receiver_account_id, 'DEBIT', v_original.amount_paise,
            v_sender_bal - v_original.amount_paise, 'Reversal debit: ' || p_reversal_ref);

    -- CREDIT the sender (contractor) — returning the amount
    VALUES (v_reversal.id, v_original.sender_account_id, 'CREDIT', v_original.amount_paise,
            v_receiver_bal + v_original.amount_paise, 'Reversal credit: ' || p_reversal_ref);

    -- Mark reversal as SUCCESS
    UPDATE payment_transactions SET status = 'SUCCESS', updated_at = NOW()
    WHERE id = v_reversal.id
    RETURNING * INTO v_reversal;

    -- Mark original transaction as REVERSED
    UPDATE payment_transactions SET status = 'REVERSED', updated_at = NOW()
    WHERE id = p_original_transaction_id;

    RETURN row_to_json(v_reversal)::JSONB;

EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END;
$$;


--
-- Name: sync_users_to_profiles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_users_to_profiles() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    VALUES (NEW.id, NEW.role, NEW.phone, NEW.email, NEW.locale, NEW.is_active, NEW.created_at, NEW.updated_at)
    ON CONFLICT (id) DO UPDATE
    SET role = EXCLUDED.role,
        phone = EXCLUDED.phone,
        email = EXCLUDED.email,
        locale = EXCLUDED.locale,
        is_active = EXCLUDED.is_active,
        updated_at = NOW();
    RETURN NEW;
END;
$$;


--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


