--
-- Name: contract_financial_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.contract_financial_summary AS
 SELECT wc.id AS contract_id,
    wc.contract_code,
    wc.worker_id,
    wc.contractor_id,
    wc.project_id,
    wc.worksite_id,
    wc.status AS contract_status,
    wc.daily_wage AS daily_wage_paise,
    (COALESCE(count(DISTINCT ae.date) FILTER (WHERE (ae.status = 'VERIFIED'::public.attendance_status)), (0)::bigint))::integer AS verified_days_count,
    (COALESCE(sum(wc.daily_wage) FILTER (WHERE (ae.status = 'VERIFIED'::public.attendance_status)), (0)::numeric))::bigint AS total_earned_paise,
    COALESCE(pt.total_paid_paise, (0)::bigint) AS total_paid_paise,
    COALESCE(pt.total_claimed_paise, (0)::bigint) AS total_claimed_paise,
    ((COALESCE(sum(wc.daily_wage) FILTER (WHERE (ae.status = 'VERIFIED'::public.attendance_status)), (0)::numeric) - (COALESCE(pt.total_paid_paise, (0)::bigint))::numeric))::bigint AS outstanding_paise
   FROM ((public.work_contracts wc
     LEFT JOIN public.attendance_events ae ON ((ae.contract_id = wc.id)))
     LEFT JOIN ( SELECT payment_transactions.contract_id,
            (COALESCE(sum(payment_transactions.amount_paise) FILTER (WHERE (payment_transactions.status = ANY (ARRAY['WORKER_CONFIRMED'::public.payment_status, 'SUCCESS'::public.payment_status]))), (0)::numeric))::bigint AS total_paid_paise,
            (COALESCE(sum(payment_transactions.amount_paise) FILTER (WHERE (payment_transactions.status = 'PAID_CLAIMED'::public.payment_status)), (0)::numeric))::bigint AS total_claimed_paise
           FROM public.payment_transactions
          GROUP BY payment_transactions.contract_id) pt ON ((pt.contract_id = wc.id)))
  GROUP BY wc.id, wc.contract_code, wc.worker_id, wc.contractor_id, wc.project_id, wc.worksite_id, wc.status, wc.daily_wage, pt.total_paid_paise, pt.total_claimed_paise;


