    description text NOT NULL,
    status public.dispute_status_enum DEFAULT 'OPEN'::public.dispute_status_enum NOT NULL,
    priority public.dispute_priority_enum DEFAULT 'MEDIUM'::public.dispute_priority_enum NOT NULL,
    raised_by_user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    amount_claimed_paise bigint DEFAULT 0 NOT NULL,
    evidence_photo_url text,
    evidence_voice_url text,
    voice_transcription text,
    linked_attendance_event_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    linked_ledger_entry_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    contractor_counter_statement text,
