    is_deadline_missed boolean DEFAULT false NOT NULL,
    is_settled boolean DEFAULT false NOT NULL,
    settled_at timestamp with time zone,
    settlement_ledger_entry_id uuid,
    CONSTRAINT check_dispute_ruling_decision CHECK (((ruling_decision IS NULL) OR (ruling_decision = ANY (ARRAY['DISMISS'::text, 'ORDER_PAYMENT'::text, 'PARTIAL_SETTLEMENT'::text]))))
);


