--
-- Name: TABLE issued_credentials; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.issued_credentials IS 'Tamper-evident work record credentials issued to workers. Chained to the latest append-only double-entry wage ledger hash.';


--
-- Name: COLUMN issued_credentials.credential_ref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.issued_credentials.credential_ref IS 'Human-readable unique verification reference, e.g. WR-20260928-8F2B.';


--
-- Name: COLUMN issued_credentials.snapshot_payload; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.issued_credentials.snapshot_payload IS 'Canonical JSON snapshot of verified metrics (shifts, earnings, GPS, disputes, tier) at issuance time.';


--
-- Name: COLUMN issued_credentials.credential_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.issued_credentials.credential_hash IS 'SHA-256 of canonical snapshot payload concatenated with ledger_hash_at_issuance.';


