--

CREATE TABLE public.job_completion_statements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employment_relationship_id uuid NOT NULL,
    contract_id uuid NOT NULL,
    worker_id uuid NOT NULL,
    contractor_id uuid NOT NULL,
    project_id uuid NOT NULL,
    work_type text NOT NULL,
    contract_period_start date NOT NULL,
    contract_period_end date,
    acceptance_date timestamp with time zone NOT NULL,
    daily_wage_paise bigint NOT NULL,
    verified_workdays integer DEFAULT 0 NOT NULL,
    total_earned_paise bigint DEFAULT 0 NOT NULL,
    total_paid_paise bigint DEFAULT 0 NOT NULL,
    outstanding_paise bigint DEFAULT 0 NOT NULL,
    total_disputes integer DEFAULT 0 NOT NULL,
    open_disputes integer DEFAULT 0 NOT NULL,
    resolved_disputes integer DEFAULT 0 NOT NULL,
    settlement_status public.settlement_status_enum NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    generated_by uuid NOT NULL,
    CONSTRAINT job_completion_statements_daily_wage_paise_check CHECK ((daily_wage_paise > 0)),
    CONSTRAINT job_completion_statements_open_disputes_check CHECK ((open_disputes >= 0)),
    CONSTRAINT job_completion_statements_resolved_disputes_check CHECK ((resolved_disputes >= 0)),
    CONSTRAINT job_completion_statements_total_disputes_check CHECK ((total_disputes >= 0)),
    CONSTRAINT job_completion_statements_total_earned_paise_check CHECK ((total_earned_paise >= 0)),
    CONSTRAINT job_completion_statements_total_paid_paise_check CHECK ((total_paid_paise >= 0)),
    CONSTRAINT job_completion_statements_verified_workdays_check CHECK ((verified_workdays >= 0))
);


--
-- Name: TABLE job_completion_statements; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.job_completion_statements IS 'Immutable record generated when a work contract/employment ends. settlement_status is computed from reconciliation at generation time and never updated. outstanding_paise > 0 → OUTSTANDING_PAYMENT. outstanding_paise = 0 → SETTLED.';


--
-- Name: COLUMN job_completion_statements.outstanding_paise; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.job_completion_statements.outstanding_paise IS 'total_earned_paise - total_paid_paise. May be negative if overpaid (rare edge case).';


--
-- Name: COLUMN job_completion_statements.settlement_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.job_completion_statements.settlement_status IS 'SETTLED: all earned wages fully paid. OUTSTANDING_PAYMENT: unpaid wages remain.';


