--
-- Name: worker_financial_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.worker_financial_summary AS
 WITH attendance_aggregates AS (
         SELECT ae.worker_id,
            count(DISTINCT ae.date) FILTER (WHERE (ae.status = 'VERIFIED'::public.attendance_status)) AS verified_days_count,
            (COALESCE(sum(wc.daily_wage) FILTER (WHERE (ae.status = 'VERIFIED'::public.attendance_status)), (0)::numeric))::bigint AS total_earned_paise
           FROM (public.attendance_events ae
             JOIN public.work_contracts wc ON ((wc.id = ae.contract_id)))
          GROUP BY ae.worker_id
        ), payment_aggregates AS (
         SELECT pt.worker_id,
            (COALESCE(sum(pt.amount_paise) FILTER (WHERE (pt.status = ANY (ARRAY['WORKER_CONFIRMED'::public.payment_status, 'SUCCESS'::public.payment_status]))), (0)::numeric))::bigint AS total_paid_paise,
            (COALESCE(sum(pt.amount_paise) FILTER (WHERE (pt.status = 'PAID_CLAIMED'::public.payment_status)), (0)::numeric))::bigint AS total_claimed_paise
           FROM public.payment_transactions pt
          GROUP BY pt.worker_id
        ), contract_aggregates AS (
         SELECT wc.worker_id,
            count(wc.id) AS total_contracts_count,
            count(wc.id) FILTER (WHERE (wc.status = 'ACTIVE'::public.contract_status)) AS active_contracts_count
           FROM public.work_contracts wc
          GROUP BY wc.worker_id
        )
 SELECT w.id AS worker_id,
    w.user_id,
    w.full_name,
    w.internal_worker_id,
    w.occupation,
    w.skill_category,
    (COALESCE(aa.verified_days_count, (0)::bigint))::integer AS verified_days_count,
    COALESCE(aa.total_earned_paise, (0)::bigint) AS total_earned_paise,
    COALESCE(pa.total_paid_paise, (0)::bigint) AS total_paid_paise,
    COALESCE(pa.total_claimed_paise, (0)::bigint) AS total_claimed_paise,
    (COALESCE(aa.total_earned_paise, (0)::bigint) - COALESCE(pa.total_paid_paise, (0)::bigint)) AS outstanding_paise,
    (COALESCE(ca.total_contracts_count, (0)::bigint))::integer AS total_contracts_count,
    (COALESCE(ca.active_contracts_count, (0)::bigint))::integer AS active_contracts_count
   FROM (((public.workers w
     LEFT JOIN attendance_aggregates aa ON ((aa.worker_id = w.id)))
     LEFT JOIN payment_aggregates pa ON ((pa.worker_id = w.id)))
     LEFT JOIN contract_aggregates ca ON ((ca.worker_id = w.id)));


